import{_ as a,o as t,c as o,a3 as n}from"./chunks/framework.D0WMbOy-.js";const g=JSON.parse('{"title":"Upgrade notes","description":"","frontmatter":{},"headers":[],"relativePath":"operations/upgrading.md","filePath":"operations/upgrading.md","lastUpdated":1793422199000}'),s={name:"operations/upgrading.md"};function i(r,e,d,h,c,l){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="upgrade-notes" tabindex="-1">Upgrade notes <a class="header-anchor" href="#upgrade-notes" aria-label="Permalink to &quot;Upgrade notes&quot;">​</a></h1><p>Most releases need nothing from you beyond upgrading the package. A release that does has a section here, newest first, saying what changed, what to do, and how to check it is done. Read every section between the version you run and the one you are installing. The GitHub release for such a version leads with the same notes, and the Arch package prints a reminder when an upgrade crosses it.</p><p>Upgrade through the same package channel you installed, as described in <a href="/development/getting-started/installation#upgrade-or-remove">Installation</a>.</p><h2 id="v0-2-0" tabindex="-1">v0.2.0 <a class="header-anchor" href="#v0-2-0" aria-label="Permalink to &quot;v0.2.0&quot;">​</a></h2><p>This release replaces per-dataset actors with <a href="/development/guide/datasets">actor roots</a>. Stop the daemon before upgrading, and check the points below before starting it again.</p><h3 id="grant-rename-on-every-destination" tabindex="-1">Grant <code>rename</code> on every destination <a class="header-anchor" href="#grant-rename-on-every-destination" aria-label="Permalink to &quot;Grant `rename` on every destination&quot;">​</a></h3><p>Boomerangz now renames a placeholder dataset aside when a dataset gets a replica of its own where it had only held other replicas, so destinations need the <code>rename</code> permission in addition to what they had. Add it wherever you delegated permissions to the receiving account, for local destinations and on each remote:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup/boomerangz</span></span></code></pre></div><p>Use the account and dataset from your own <code>zfs allow</code> setup, as shown in <a href="/development/guide/security#destination-datasets">Security</a>, and check the result with <code>zfs allow backup/boomerangz</code>. Transfers that do not replace a placeholder keep working without it; one that does stops with a permission preflight error naming what is missing.</p><p>The daemon now also checks every destination for the permissions it may need, <code>rename</code> included, when it first reaches it, and reports anything missing as a warning in <code>boomerangz status</code> and in its log, naming the destination, the account and the permissions. After starting the upgraded daemon, run <code>boomerangz status</code> once a transfer has reached each destination; it lists no <code>WARNINGS</code> when every destination grants what it needs. A remote is checked only once its endpoint opens. After granting a missing permission, run <code>boomerangz config reload</code> to have the daemon check again. See <a href="/development/operations/#destination-permissions">Destination permissions</a>.</p><h3 id="review-how-your-datasets-are-grouped" tabindex="-1">Review how your datasets are grouped <a class="header-anchor" href="#review-how-your-datasets-are-grouped" aria-label="Permalink to &quot;Review how your datasets are grouped&quot;">​</a></h3><p>An enabled dataset with no enabled ancestor is now an actor root, and every enabled dataset beneath it is one of its members rather than a root of its own. Before starting the daemon, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boomerangz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dataset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>A dataset that used to replicate on its own and now reads <code>member</code> is snapshotted, pruned and sent by its root, on its own retention grid and with its own send options. <code>trigger</code>, <code>dataset adopt</code> and <code>dataset reseed</code> refuse a member and name its root; operate on the root instead. If a root&#39;s transfer then reports that an existing destination has no common base, reseed that root&#39;s target as described in <a href="/development/operations/recovery#reseed-a-target">Recovery</a>.</p><p>A dataset set to <code>enabled=off</code> beneath a root is excluded from it. A root with <code>replicate=on</code> still sends its whole subtree as one <code>zfs send -R</code> package.</p><h3 id="check-for-blocked-destinations" tabindex="-1">Check for blocked destinations <a class="header-anchor" href="#check-for-blocked-destinations" aria-label="Permalink to &quot;Check for blocked destinations&quot;">​</a></h3><p>When two roots&#39; replicas would overlap on a destination, that destination is now blocked for the roots involved, rather than replication failing at receive time. <code>dataset list</code> names blocked destinations beside each root, and <code>dataset inspect</code> says what each collides with. A root keeps snapshotting, pruning and sending to its other destinations. Fix the mapping - usually with <code>discard</code> or a different destination - and the block clears on the next scan.</p><h3 id="worth-knowing" tabindex="-1">Worth knowing <a class="header-anchor" href="#worth-knowing" aria-label="Permalink to &quot;Worth knowing&quot;">​</a></h3><ul><li><code>status</code> and the job log report a new state, <code>waiting-lock</code>, for a transfer held back by another job&#39;s lock on the same destination. Anything that matches job states should treat it as running.</li><li><code>dataset abort-receive</code> discards an interrupted receive that keeps failing to resume. See <a href="/development/operations/recovery#discard-an-interrupted-receive">Recovery</a>.</li><li>Turning <code>replicate=on</code> for a root that replicated member by member needs a reseed of its targets; turning it off again does not.</li></ul>',19)])])}const u=a(s,[["render",i]]);export{g as __pageData,u as default};
